parameters.body/messageBody:
{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "body": [
    {
      "type": "Container",
      "style": "emphasis",
      "bleed": true,
      "items": [
        {
          "type": "TextBlock",
          "text": "🚨 Flow Failure Alert",
          "weight": "Bolder",
          "size": "Medium",
          "wrap": true
        },
        {
          "type": "FactSet",
          "facts": [
{           
  "title": "📦 Solution:",
  "value": "@{triggerBody()['text']}"
},
{
              "title": "⚙️ Workflow:",
              "value": "@{variables('FlowName')}"
            },
            {
              "title": "🧨 Error:",
              "value": "@{variables('Error')}"
            }
          ]
        }
      ]
    }
  ],
  "actions": [
    {
      "type": "Action.OpenUrl",
      "title": "🔗 Open Flow Run",
      "url": "@{trim(variables('FlowUrl'))}"
    }
  ]
}
